def blocks(g):
    n=len(g); m=len(g[0]); out=[]
    for r in range(n-1):
        for c in range(m-1):
            if g[r][c]==g[r+1][c] and g[r][c]==g[r][c+1] and g[r][c]==g[r+1][c+1]:
                out.append((r,c,g[r][c]))
    return out
for k in ['Demo pair 1 input','Demo pair 2 input']:
    b=blocks(G[k])
    print(k,b)

def comps(g,val):
    n=len(g); m=len(g[0]); seen=[[False]*m for _ in range(n)]; out=[]
    for r in range(n):
        for c in range(m):
            if g[r][c]==val and not seen[r][c]:
                st=[(r,c)]; cl=[]; seen[r][c]=True
                while st:
                    x,y=st.pop(); cl.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx,ny=x+dx,y+dy
                        if 0<=nx<n and 0<=ny<m and g[nx][ny]==val and not seen[nx][ny]:
                            seen[nx][ny]=True; st.append((nx,ny))
                out.append(cl)
    return out
